// === Tab: mySketch ===
let pg;
let theShader;

function preload(){
	theShader = createShader(vert, frag);
}

function setup() {
  createCanvas(600, 600, WEBGL);

  pg = createGraphics(600, 600);
}

function draw() {
	//pg.clear();
	pg.background("#143642");
  pg.noStroke();
	pg.fill("#0F8B8D");
  pg.circle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 300);

	shader(theShader);
	theShader.setUniform("u_resolution", [pg.width, pg.height]);
	theShader.setUniform("u_time", millis()/1000);
	theShader.setUniform("tex0", pg);

	quad(-1, -1, 1, -1, 1, 1, -1, 1);
}

// === Tab: vert ===
const vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	void main() {
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

		gl_Position = positionVec4;
	}
`;

// === Tab: frag ===
const frag = `
  #ifdef GL_ES
  precision mediump float;
  #endif

  uniform vec2 u_resolution;
  uniform float u_time;
	uniform sampler2D tex0;

	void main(){
		float dv = 4.0;

		vec2 uv = gl_FragCoord.xy/u_resolution;
		uv*=0.5;

		vec2 fuv = fract(uv*dv);

		vec2 ruv = floor(uv*dv)/dv;

		vec4 tex = texture2D(tex0,vec2(fuv.x, 1.0-fuv.y));

		vec3 col = vec3(tex.rgb);
		col = col-fuv.x*(1.0-fuv.y)*ruv.x*(1.0-ruv.y);
		//uv.x*(1.0-uv.y) bottom right corner gives 1, top left gives 0

		gl_FragColor = vec4(col, 1.0);
	}
`;

